      const thumb = c.querySelector('.card-thumb');
      const badge = c.querySelector('.badge');
      const cs = getComputedStyle(c);
      const ts = thumb ? getComputedStyle(thumb) : null;
      const bs = badge ? getComputedStyle(badge) : null;
      out.push({
        i,
        card: c.getBoundingClientRect().toJSON(),
        thumb: thumb ? thumb.getBoundingClientRect().toJSON() : null,
        thumbH: ts && ts.height,
        badge: badge ? { rect: badge.getBoundingClientRect().toJSON(), text: badge.textContent, top: bs.top, right: bs.right, display: bs.display } : null,
        overflow: cs.overflow,
      });
    });
    return { out, scrollWidth: document.documentElement.scrollWidth, clientWidth: document.documentElement.clientWidth };
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();
